# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">STANDART UZUNLUK ÖLÇME BİRİMLERİ VE PROBLEM ÇÖZME (MAT.6.1.8)</text>\n  <rect x="20" y="48" width="660" height="88" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Uzunluk Ölçme Birimi Merdiveni (Ölçüt Birim: Metre = m)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">km ⟷ hm ⟷ dam ⟷ [ m ] ⟷ dm ⟷ cm ⟷ mm</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11.5" fill="#2563eb">Aşağı inerken her basamakta 10 ile çarpılır (×10) · Yukarı çıkarken her basamakta 10\'a bölünür (÷10)</text>\n\n  <rect x="20" y="148" width="320" height="92" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Problem Çözme Kuralı: Ortak Birim</text>\n  <text x="35" y="196" font-size="11.5" fill="#14532d">• Farklı birimlerle verilen uzunluklar toplanmadan</text>\n  <text x="35" y="214" font-size="11.5" fill="#14532d">veya çıkarılmadan önce istenen ortak birime çevrilir.</text>\n  <text x="180" y="232" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Örnek: 2,4 km + 350 m = 2400 m + 350 m = 2750 m</text>\n\n  <rect x="360" y="148" width="320" height="92" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="520" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Parça Sayısı ve Kesim Sayısı İlişkisi</text>\n  <text x="375" y="196" font-size="11.5" fill="#713f12">• Çember/halka olmayan düz bir tel veya tahta</text>\n  <text x="375" y="214" font-size="11.5" fill="#713f12">N eş parçaya ayrıldığında (N - 1) kez kesim yapılır.</text>\n  <text x="520" y="232" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">3,6 m = 360 cm tel ➔ 60 cm\'lik 6 parça (5 kesim)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSTATİSTİKSEL ARAŞTIRMA SÜRECİ VE VERİ TÜRLERİ (MAT.6.5.1)</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">1. Kategorik (Nitel) Veri</text>\n  <text x="38" y="98" font-size="11.5" fill="#831843">• Sözel ifade edilen, nitelik veya grup bildiren veridir.</text>\n  <text x="38" y="122" font-size="11.5" fill="#831843">• Sayısal büyüklük ve dört işlem anlamı taşımaz.</text>\n  <text x="38" y="148" font-size="11.5" font-weight="bold" fill="#9d174d">Örnek Kategorik Veriler:</text>\n  <text x="38" y="170" font-size="11.5" fill="#831843">• Öğrencilerin en sevdiği spor dalı (yüzme, okçuluk)</text>\n  <text x="38" y="192" font-size="11.5" fill="#831843">• Göz renkleri, kan grupları, tercih edilen meyveler</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Özetleme: Tepe Değer (Mod) ve Sıklık Tablosu</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">2. Nicel (Kesikli) Veri</text>\n  <text x="378" y="98" font-size="11.5" fill="#581c87">• Sayma yoluyla elde edilen sayısal verilerdir.</text>\n  <text x="378" y="122" font-size="11.5" fill="#581c87">• Ara değer (kesirli/ondalık) almaz, tam sayı belirtir.</text>\n  <text x="378" y="148" font-size="11.5" font-weight="bold" fill="#6b21a8">Örnek Nicel (Kesikli) Veriler:</text>\n  <text x="378" y="170" font-size="11.5" fill="#581c87">• Öğrencilerin kardeş sayısı (0, 1, 2, 3...)</text>\n  <text x="378" y="192" font-size="11.5" fill="#581c87">• Bir ayda okunan dergi sayısı, maçta atılan gol sayısı</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Özetleme: Ortalama, Ortanca, Tepe Değer, Açıklık</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VERİ GÖRSELLEŞTİRME VE ÖZETLEME ARAÇLARI (MAT.6.5.1.d)</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Nokta Grafiği: Kardeş Sayısı Dağılımı</text>\n  <line x1="55" y1="185" x2="305" y2="185" stroke="#0f172a" stroke-width="2"/>\n  <text x="85" y="205" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">0</text>\n  <text x="145" y="205" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">1</text>\n  <text x="205" y="205" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">2</text>\n  <text x="265" y="205" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">3</text>\n  <!-- 0 kardeş: 2 kişi -->\n  <circle cx="85" cy="170" r="6" fill="#0284c7"/><circle cx="85" cy="152" r="6" fill="#0284c7"/>\n  <!-- 1 kardeş: 4 kişi -->\n  <circle cx="145" cy="170" r="6" fill="#0284c7"/><circle cx="145" cy="152" r="6" fill="#0284c7"/>\n  <circle cx="145" cy="134" r="6" fill="#0284c7"/><circle cx="145" cy="116" r="6" fill="#0284c7"/>\n  <!-- 2 kardeş: 3 kişi -->\n  <circle cx="205" cy="170" r="6" fill="#0284c7"/><circle cx="205" cy="152" r="6" fill="#0284c7"/>\n  <circle cx="205" cy="134" r="6" fill="#0284c7"/>\n  <!-- 3 kardeş: 1 kişi -->\n  <circle cx="265" cy="170" r="6" fill="#0284c7"/>\n  <text x="180" y="226" text-anchor="middle" font-size="11" fill="#155e75">Veriler: 0, 0, 1, 1, 1, 1, 2, 2, 2, 3 (Toplam 10 öğrenci)</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Kök-Yaprak Gösterimi ve Özet Ölçüler</text>\n  <text x="380" y="98" font-size="12" font-weight="bold" fill="#9a3412">Kök (Onlar) | Yaprak (Birler) [Notlar]</text>\n  <text x="410" y="120" font-size="12" fill="#7c2d12">7 | 0  5  5  8   ➔ (70, 75, 75, 78)</text>\n  <text x="410" y="142" font-size="12" fill="#7c2d12">8 | 2  4  9      ➔ (82, 84, 89)</text>\n  <text x="410" y="164" font-size="12" fill="#7c2d12">9 | 0  6         ➔ (90, 96)</text>\n  <text x="380" y="190" font-size="11.5" font-weight="bold" fill="#c2410c">• Tepe Değer (Mod): 75 (en çok tekrar eden)</text>\n  <text x="380" y="208" font-size="11.5" font-weight="bold" fill="#c2410c">• Ortanca (Medyan): 82 (tam ortadaki 5. veri)</text>\n  <text x="380" y="226" font-size="11.5" font-weight="bold" fill="#c2410c">• Açıklık: 96 - 70 = 26 (En büyük - En küçük)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
